import pytest

from discount import discount_rate


@pytest.mark.parametrize(
    "total",
    [0, 50, 99.99, 100.0, 100.01, 150, 1000],
)
def test_member_gets_twenty_percent_regardless_of_total(total):
    assert discount_rate(total, member=True) == 0.2


def test_member_precedence_over_high_total_returns_member_rate():
    assert discount_rate(500, member=True) == 0.2


def test_non_member_at_exact_threshold_gets_ten_percent():
    assert discount_rate(100.0) == 0.1


@pytest.mark.parametrize(
    "total, expected",
    [
        (99.99, 0.0),
        (100.01, 0.1),
    ],
)
def test_non_member_threshold_sides(total, expected):
    assert discount_rate(total, member=False) == expected


@pytest.mark.parametrize("total", [0, 50])
def test_non_member_below_threshold_returns_zero_discount(total):
    assert discount_rate(total) == 0.0


@pytest.mark.parametrize("total", [150, 1000])
def test_non_member_above_threshold_returns_ten_percent(total):
    assert discount_rate(total, member=False) == 0.1


@pytest.mark.parametrize(
    "total, member",
    [
        (-1, False),
        (-1, True),
        (-0.01, False),
    ],
)
def test_negative_total_raises_value_error(total, member):
    with pytest.raises(ValueError, match="negative total"):
        discount_rate(total, member=member)


def test_negative_total_member_raises_before_membership_branch():
    with pytest.raises(ValueError, match="negative total"):
        discount_rate(-50, member=True)

import pytest

from models import Item


@pytest.mark.parametrize(
    "price, quantity, expected",
    [
        (10.0, 3, 30.0),
        (2.5, 4, 10.0),
        (0.5, 7, 3.5),
    ],
)
def test_subtotal_returns_price_times_quantity(price, quantity, expected):
    assert Item(price=price, quantity=quantity).subtotal() == expected


def test_default_quantity_is_one_and_subtotal_equals_price():
    item = Item(price=19.99)
    assert item.quantity == 1
    assert item.subtotal() == 19.99


@pytest.mark.parametrize(
    "price, quantity",
    [
        (0.0, 5),
        (10.0, 0),
        (0.0, 0),
    ],
)
def test_zero_values_produce_zero_subtotal_without_raising(price, quantity):
    assert Item(price=price, quantity=quantity).subtotal() == 0.0


@pytest.mark.parametrize(
    "price, quantity",
    [
        (-0.01, 1),
        (-5.0, 2),
        (-100.0, 3),
    ],
)
def test_negative_price_raises_value_error(price, quantity):
    with pytest.raises(ValueError, match="negative price or quantity"):
        Item(price=price, quantity=quantity).subtotal()


@pytest.mark.parametrize(
    "price, quantity",
    [
        (10.0, -1),
        (2.5, -10),
    ],
)
def test_negative_quantity_raises_value_error(price, quantity):
    with pytest.raises(ValueError, match="negative price or quantity"):
        Item(price=price, quantity=quantity).subtotal()


def test_both_price_and_quantity_negative_raise_single_value_error():
    with pytest.raises(ValueError, match="negative price or quantity"):
        Item(price=-1.0, quantity=-2).subtotal()


def test_validation_happens_at_call_time_not_construction():
    item = Item(price=5.0, quantity=-1)
    with pytest.raises(ValueError, match="negative price or quantity"):
        item.subtotal()


def test_mutated_negative_quantity_makes_next_subtotal_raise():
    item = Item(price=3.0, quantity=2)
    assert item.subtotal() == 6.0
    item.quantity = -1
    with pytest.raises(ValueError, match="negative price or quantity"):
        item.subtotal()

import pytest

from models import Item
from order import order_total


@pytest.mark.parametrize(
    "items, expected",
    [
        ([Item(10.0, 2), Item(5.0, 1)], 25.0),
        ([Item(20.0, 3)], 60.0),
    ],
)
def test_non_member_below_threshold_has_no_discount(items, expected):
    assert order_total(items, member=False) == expected


@pytest.mark.parametrize(
    "items, expected",
    [
        ([Item(50.0, 3)], 135.0),
        ([Item(120.0, 1)], 108.0),
    ],
)
def test_non_member_above_threshold_gets_ten_percent_discount(items, expected):
    assert order_total(items, member=False) == expected


@pytest.mark.parametrize(
    "items, expected",
    [
        ([Item(50.0, 1)], 40.0),
        ([Item(100.0, 2)], 160.0),
    ],
)
def test_member_gets_twenty_percent_discount_regardless_of_total(items, expected):
    assert order_total(items, member=True) == expected


def test_non_member_total_exactly_at_threshold_gets_ten_percent_discount():
    assert order_total([Item(100.0, 1)], member=False) == 90.0


def test_non_member_total_just_below_threshold_gets_no_discount():
    assert order_total([Item(99.99, 1)], member=False) == 99.99


def test_empty_item_list_returns_zero_total():
    assert order_total([]) == 0.0


def test_subthreshold_total_is_rounded_to_two_decimals():
    assert order_total([Item(33.333, 1)], member=False) == 33.33


def test_negative_item_price_propagates_value_error():
    with pytest.raises(ValueError, match="negative price or quantity"):
        order_total([Item(10.0, 1), Item(-5.0, 1)], member=False)


def test_negative_item_price_raises_even_for_member_order():
    with pytest.raises(ValueError, match="negative price or quantity"):
        order_total([Item(-1.0, 1)], member=True)


def test_single_member_item_with_zero_subtotal_returns_zero():
    assert order_total([Item(0.0, 0)], member=True) == 0.0


def test_order_total_uses_item_subtotal_quantity_product():
    assert order_total([Item(10.0, 3)], member=False) == 30.0
